
from pathlib import Path
import pandas as pd

# Locate the project directories.
ROOT = Path(__file__).resolve().parents[1]
EVIDENCE = ROOT / "evidence" / "F-001"
OUTPUTS = ROOT / "outputs"


def load_csv(path):
    return pd.read_csv(path, dtype=str).fillna("")


def main():
    # Read the original and post-remediation exports.
    baseline = load_csv(EVIDENCE / "application_access_export.csv")
    remediation = load_csv(EVIDENCE / "remediation_access_export.csv")

    # Read the reports generated by our first Python script.
    baseline_exceptions = load_csv(OUTPUTS / "baseline_exceptions.csv")
    remediation_exceptions = load_csv(OUTPUTS / "remediation_exceptions.csv")

    # Compare employee/application pairs across both exports.
    baseline_accounts = list(
        zip(baseline["employee_id"], baseline["application"])
    )
    remediation_accounts = list(
        zip(remediation["employee_id"], remediation["application"])
    )

    sample_matched = (
        len(baseline_accounts) == len(set(baseline_accounts))
        and len(remediation_accounts) == len(set(remediation_accounts))
        and set(baseline_accounts) == set(remediation_accounts)
    )

    # Generate a CSV summary.
    summary = pd.DataFrame({
        "metric": [
            "Accounts Reviewed",
            "Access Exceptions",
        ],
        "baseline": [
            len(baseline),
            len(baseline_exceptions),
        ],
        "post_remediation": [
            len(remediation),
            len(remediation_exceptions),
        ],
    })

    OUTPUTS.mkdir(parents=True, exist_ok=True)
    summary.to_csv(OUTPUTS / "reconciliation_summary.csv", index=False)

    coverage_result = (
        "Matched across the two sample exports"
        if sample_matched
        else "Mismatch or duplicate accounts detected - investigate"
    )

    # Generate a Markdown report for management.
    report = f"""# F-001 Automated Access Reconciliation Summary

> SIMULATED GRC PORTFOLIO EXERCISE

## Results

| Metric | Baseline | Post-Remediation |
|---|---:|---:|
| Application accounts reviewed | {len(baseline)} | {len(remediation)} |
| Terminated-user active-access exceptions | {len(baseline_exceptions)} | {len(remediation_exceptions)} |

## Sample Coverage Check

{coverage_result}

This check compares account identifiers across the two provided
exports. It does not verify completeness of the enterprise account
population.

## Assessment

The original export identified {len(baseline_exceptions)} access
exceptions. The post-remediation export identified
{len(remediation_exceptions)} exceptions.

Finding F-001 remains In Progress. Additional evidence is
required to establish recurring weekly control effectiveness.

## Evidence References

- evidence/F-001/hr_termination_records.csv
- evidence/F-001/application_access_export.csv
- evidence/F-001/remediation_access_export.csv
- outputs/baseline_exceptions.csv
- outputs/remediation_exceptions.csv

## Limitations

All evidence is synthetic. Results reflect only the supplied sample.
No live systems were accessed or modified.
"""

    report_path = OUTPUTS / "reconciliation_summary.md"
    report_path.write_text(report, encoding="utf-8")

    print("Automated summary generated successfully.")
    print(f"Baseline exceptions: {len(baseline_exceptions)}")
    print(f"Post-remediation exceptions: {len(remediation_exceptions)}")
    print(f"Sample coverage: {coverage_result}")
    print(f"Summary report: {report_path}")


if __name__ == "__main__":
    main()
